# Generated by the network debugging agent
# Request: find the largest MTU that works from ns1 to ns2
# TYPE: one-sided
# Re-run: python tool_builder.py --run tools/largest_mtu.py
#!/usr/bin/env python3
"""Find largest MTU (IP total length) that works from ns1 to ns2 without fragmentation."""
import os
import subprocess
import sys
import time

TARGET = "10.0.0.2"
MIN_MTU = 68
FALLBACK_MAX_MTU = 1500
PING_COUNT = "1"
PING_WAIT = "1"  # seconds per probe
SUBPROC_TIMEOUT = 3  # seconds, must be > PING_WAIT
OVERALL_BUDGET = 20.0  # keep whole run well under 25s

def get_local_cap():
    """Read local interface MTUs from sysfs to cap search. Returns (cap, list)."""
    candidates = []
    try:
        base = "/sys/class/net"
        for iface in os.listdir(base):
            if iface == "lo":
                continue
            p = os.path.join(base, iface, "mtu")
            try:
                with open(p, "r") as f:
                    mtu = int(f.read().strip())
                    candidates.append((iface, mtu))
            except Exception:
                continue
    except Exception as e:
        print(f"[info] could not read sysfs MTUs: {e}")
        return FALLBACK_MAX_MTU, []
    if not candidates:
        return FALLBACK_MAX_MTU, []
    cap = max(m for _, m in candidates)
    # sanity clamp
    if cap < MIN_MTU:
        cap = FALLBACK_MAX_MTU
    if cap > 9000:
        cap = 9000
    return cap, candidates

def probe_mtu(mtu):
    """Ping once with DF set. Returns (ok, raw_output, elapsed, returncode)."""
    payload = mtu - 28  # 20 IP + 8 ICMP
    if payload < 0:
        return False, "invalid mtu->payload", 0.0, -1
    cmd = ["ping", "-c", PING_COUNT, "-W", PING_WAIT, "-n", "-M", "do",
           "-s", str(payload), TARGET]
    start = time.monotonic()
    try:
        cp = subprocess.run(cmd, capture_output=True, text=True, timeout=SUBPROC_TIMEOUT)
        elapsed = time.monotonic() - start
        raw = (cp.stdout or "") + (cp.stderr or "")
        if not raw.strip():
            raw = f"(no output, rc={cp.returncode})"
        ok = (cp.returncode == 0)
        return ok, raw.strip(), elapsed, cp.returncode
    except subprocess.TimeoutExpired as e:
        elapsed = time.monotonic() - start
        raw = f"subprocess timeout after {elapsed:.2f}s"
        if e.stdout:
            try:
                raw += "\n" + e.stdout.decode() if isinstance(e.stdout, bytes) else str(e.stdout)
            except Exception:
                pass
        return False, raw, elapsed, -2
    except FileNotFoundError as e:
        elapsed = time.monotonic() - start
        return False, f"ping tool not found: {e}", elapsed, -3
    except Exception as e:
        elapsed = time.monotonic() - start
        return False, f"probe exception: {e}", elapsed, -4

def print_probe(mtu, ok, raw, elapsed, rc):
    payload = mtu - 28
    status = "PASS" if ok else "FAIL"
    print(f"[probe] MTU={mtu} (payload={payload}) -> {status} rc={rc} time={elapsed:.3f}s")
    # raw evidence: single-line summary + full output indented
    for line in raw.splitlines():
        print(f"  | {line}")
    sys.stdout.flush()

def main():
    t0 = time.monotonic()
    print("=== largest MTU test ns1(10.0.0.1) -> ns2(10.0.0.2) ===")
    print(f"target: {TARGET}")
    print(f"method: ping -M do -s <mtu-28> -c {PING_COUNT} -W {PING_WAIT} (DF set, no frag)")
    cap, cands = get_local_cap()
    if cands:
        print(f"[info] local non-lo MTUs from sysfs: {cands} -> search cap={cap}")
    else:
        print(f"[info] no sysfs MTU found, using fallback cap={cap}")
    print(f"[info] search range: MIN_MTU={MIN_MTU} to MAX_MTU={cap}")
    sys.stdout.flush()

    # Test minimum
    ok_min, raw_min, el_min, rc_min = probe_mtu(MIN_MTU)
    print_probe(MIN_MTU, ok_min, raw_min, el_min, rc_min)
    if not ok_min:
        print(f"[result] FAIL: even MIN_MTU={MIN_MTU} failed. Network down or DF blocked.")
        print(f"[result] largest_working_mtu=none (min {MIN_MTU} failed)")
        print(f"[evidence] min probe rc={rc_min} time={el_min:.3f}s")
        print("=== done ===")
        return 0

    max_mtu = cap
    ok_max, raw_max, el_max, rc_max = probe_mtu(max_mtu)
    print_probe(max_mtu, ok_max, raw_max, el_max, rc_max)
    if ok_max:
        largest = max_mtu
        print(f"[result] largest_working_mtu={largest} (payload={largest-28}) - cap {max_mtu} works")
        # verify with 3 packets for solid evidence
        if time.monotonic() - t0 < OVERALL_BUDGET - 4:
            cmd = ["ping", "-c", "3", "-W", PING_WAIT, "-n", "-M", "do",
                   "-s", str(largest - 28), TARGET]
            print(f"[verify] confirming MTU={largest} with 3 packets: {' '.join(cmd)}")
            try:
                cp = subprocess.run(cmd, capture_output=True, text=True, timeout=6)
                rawv = ((cp.stdout or "") + (cp.stderr or "")).strip()
                print(f"[verify] rc={cp.returncode}")
                for line in rawv.splitlines():
                    print(f"  | {line}")
            except Exception as e:
                print(f"[verify] exception: {e}")
        print(f"[evidence] max probe rc={rc_max} time={el_max:.3f}s")
        print("=== done ===")
        return 0

    # binary search: lo=known good, hi=known bad
    lo = MIN_MTU
    hi = max_mtu
    n_probes = 2
    while hi - lo > 1:
        if time.monotonic() - t0 > OVERALL_BUDGET - 3:
            print("[warn] approaching time budget, stopping search early")
            break
        mid = (lo + hi) // 2
        ok, raw, el, rc = probe_mtu(mid)
        print_probe(mid, ok, raw, el, rc)
        n_probes += 1
        if ok:
            lo = mid
        else:
            hi = mid

    print(f"[result] largest_working_mtu={lo} (payload={lo-28}, total IP len={lo})")
    print(f"[result] smallest_failing_mtu={hi} (payload={hi-28})" if hi == lo + 1 else f"[result] upper_bound_mtu={hi} failed or untested")
    print(f"[result] probes={n_probes} range=[{MIN_MTU},{max_mtu}] target={TARGET}")
    print(f"[evidence] lo({lo}) works, hi({hi}) fails (see probes above)")

    # final verification: lo should pass with 2 packets, hi should fail with 1
    if time.monotonic() - t0 < OVERALL_BUDGET - 5:
        for mtu_v, cnt in [(lo, "2"), (hi, "1")]:
            payload = mtu_v - 28
            cmd = ["ping", "-c", cnt, "-W", PING_WAIT, "-n", "-M", "do",
                   "-s", str(payload), TARGET]
            print(f"[verify] MTU={mtu_v} x{cnt}: {' '.join(cmd)}")
            try:
                cp = subprocess.run(cmd, capture_output=True, text=True, timeout=5)
                rawv = ((cp.stdout or "") + (cp.stderr or "")).strip() or f"(no output rc={cp.returncode})"
                print(f"[verify] MTU={mtu_v} rc={cp.returncode}")
                for line in rawv.splitlines():
                    print(f"  | {line}")
            except Exception as e:
                print(f"[verify] MTU={mtu_v} exception: {e}")
    elapsed_total = time.monotonic() - t0
    print(f"[info] total_time={elapsed_total:.2f}s")
    print("=== done ===")
    return 0

if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception as e:
        # real bug: allow non-zero; network failures already handled with exit 0 above
        print(f"[bug] unhandled exception: {e}")
        import traceback
        traceback.print_exc()
        sys.exit(2)
